package com.gukhan.ainlp.document;
import java.io.*;import java.util.*;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import org.apache.poi.ss.usermodel.*;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;
@Service public class DocumentService{private final DocumentChunkRepository repo;public DocumentService(DocumentChunkRepository r){repo=r;}
public int ingest(MultipartFile file,String dept)throws IOException{String name=Objects.requireNonNull(file.getOriginalFilename()).toLowerCase();String text;if(name.endsWith(".pdf")){try(var doc=Loader.loadPDF(file.getBytes())){text=new PDFTextStripper().getText(doc);}}else if(name.endsWith(".txt"))text=new String(file.getBytes(),java.nio.charset.StandardCharsets.UTF_8);else if(name.endsWith(".xlsx")||name.endsWith(".xls")){try(var wb=WorkbookFactory.create(file.getInputStream())){StringBuilder b=new StringBuilder();for(Sheet s:wb)for(Row r:s)for(Cell c:r)b.append(c.toString()).append(' ');text=b.toString();}}else throw new IllegalArgumentException("Supported: PDF, TXT, XLS, XLSX");var chunks=chunk(text,900,120);chunks.forEach(c->repo.save(new DocumentChunk(c,dept,name)));return chunks.size();}
private List<String> chunk(String text,int size,int overlap){List<String> out=new ArrayList<>();int start=0;while(start<text.length()){int end=Math.min(text.length(),start+size);out.add(text.substring(start,end));if(end==text.length())break;start=Math.max(start+1,end-overlap);}return out;}}